package viewpoint.models;
public final class Models {public static boolean capturing;private static java.util.ArrayList<zombie.core.textures.TextureDraw.GenericDrawer> sink;public static int owns;public static void receive(zombie.core.skinnedmodel.model.WorldItemModelDrawer d){if(capturing&&sink!=null)sink.add(d);}private static void own(viewpoint.core.Frame f,int start,zombie.iso.IsoGridSquare sq,zombie.iso.IsoObject o,zombie.inventory.InventoryItem item){owns++;for(int n=start;n<f.drawers.size();n++){var d=(zombie.core.skinnedmodel.model.WorldItemModelDrawer)f.drawers.get(n);var r=d.authored();var world=new org.joml.Matrix4f().translation(-(r.x-f.camX),(r.z-f.camZ)*(float)Math.sqrt(6),-(r.y-f.camY)).scale(-1.5f,1.5f,1.5f).rotateX((float)Math.toRadians(item.worldXRotation)).rotateY((float)Math.toRadians(item.worldZRotation)).rotateZ((float)Math.toRadians(item.worldYRotation));f.scene.models.append(null,d.mesh,d.tex,item,new org.joml.Matrix4f(world).scale(.4f).get(new float[16]),false);}}}
